def objects(g):
    seen=set(); objs=[]
    for i,row in enumerate(g):
        for j,v in enumerate(row):
            if v and v!=5 and (i,j) not in seen:
                col=v; stack=[(i,j)]; cells=[]; seen.add((i,j))
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<len(g) and 0<=nx<len(g[0]) and g[ny][nx]==col and (ny,nx) not in seen:
                                seen.add((ny,nx)); stack.append((ny,nx))
                ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
                objs.append({'color':col,'cells':sorted(cells),'top':min(ys),'bot':max(ys),'left':min(xs)})
    return objs

def transform(g):
    H=len(g); W=len(g[0])
    line=[i for i,row in enumerate(g) if all(v==5 for v in row)][0]
    objs=objects(g)
    top=[o for o in objs if o['bot']<line]
    bot=[o for o in objs if o['top']>line][0]
    bnorm=norm(bot)
    keep=[o for o in top if norm(o)!=bnorm]
    keep=[o for o in keep if o['color']==max(o2['color'] for o2 in keep)]
    oh=H-line-1
    out=[[0]*W for _ in range(oh)]
    for y,x in bot['cells']: out[y-line-1][x]=bot['color']
    ycur=bot['top']-line-1
    for o in keep:
        miny=min(y for y,_ in o['cells']); minx=min(x for _,x in o['cells'])
        h=max(y for y,_ in o['cells'])-miny+1
        y0=ycur-h
        for y,x in o['cells']:
            out[y0+y-miny][bot['left']+x-minx]=o['color']
        ycur=y0
    return out

